cssCode:
html, body { 
  margin: 0; padding: 0; background: #000; overflow-x: hidden; font-family: sans-serif; 
}
.zynk-track { 
  width: 100%; height: 400vh; position: relative; 
}
#zynk-canvas { 
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; 
}
.ui-layer { 
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh; 
  display: flex; flex-direction: column; align-items: center; justify-content: center; 
  z-index: 2; pointer-events: none; 
}
/* હવામાં તરતા ટેક્સ્ટ માટે */
.float-msg { 
  position: absolute; color: #fff; font-weight: 900; opacity: 0; 
  transition: opacity 0.4s ease-out, transform 0.4s ease-out; 
  text-shadow: 0 10px 30px rgba(0,0,0,0.9); text-align: center; 
}
/* ગ્લોઇંગ બોર્ડર કાર્ડ (અંતિમ રિવીલ) */
.glow-card {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) scale(0.5);
  width: 300px; height: 400px; background: rgba(10, 10, 15, 0.8);
  border-radius: 20px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  opacity: 0; transition: opacity 0.5s, transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  overflow: hidden; pointer-events: auto; z-index: 10;
}
.glow-card.visible { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.glow-card::before {
  content: ''; position: absolute; width: 150%; height: 150%;
  background: conic-gradient(transparent, transparent, transparent, #00ffcc, #ff007f);
  animation: spinGlow 4s linear infinite; z-index: 0; opacity: 0.6;
}
.card-inner {
  position: absolute; inset: 3px; background: #050505; border-radius: 17px;
  z-index: 1; display: flex; flex-direction: column; align-items: center; justify-content: center;
  color: white; padding: 20px; text-align: center;
}
/* મેગ્નેટિક બટન */
.mag-btn {
  margin-top: 30px; padding: 15px 30px; background: transparent; color: #00ffcc;
  border: 2px solid #00ffcc; border-radius: 30px; font-weight: bold; cursor: pointer;
  transition: background 0.3s, color 0.3s;
}
.mag-btn:hover { background: #00ffcc; color: #000; box-shadow: 0 0 20px rgba(0,255,204,0.6); }

@keyframes spinGlow { 100% { transform: rotate(360deg); } }

jsCode:
const mainWrap = document.getElementById('container');
mainWrap.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;position:relative;';

mainWrap.innerHTML = `
  <div class="zynk-track">
    <canvas id="zynk-canvas"></canvas>
    <div class="ui-layer">
      <div id="msg1" class="float-msg" style="font-size:24px; color:#888; top: 75%;">Scroll to Explore ZYNK ↓</div>
      <div id="msg2" class="float-msg" style="font-size:50px; color:#ff007f;">PARTICLES SHATTER</div>
      <div id="msg3" class="float-msg" style="font-size:45px; color:#00d2ff;">OCEAN OF CODE</div>

      <div class="glow-card" id="finalCard">
        <div class="card-inner">
          <h2 style="margin:0; font-size:32px; background:linear-gradient(90deg,#00d2ff,#00ffcc); -webkit-background-clip:text; color:transparent;">MOTION ZYNC</h2>
          <p style="color:#aaa; font-size:14px; margin-top:10px;">World's Best Animations in pure CSS & JS.</p>
          <button class="mag-btn" id="mBtn">GET CODES</button>
        </div>
      </div>
    </div>
  </div>
`;

const cvs = document.getElementById('zynk-canvas');
const ctx = cvs.getContext('2d');
let W, H;
let particles = [], shapes = [];
const pCount = 1000; // મોબાઈલ માટે ઑપ્ટિમાઇઝ કરેલી સંખ્યા

function getPts(txt, size) {
  const tc = document.createElement('canvas');
  tc.width = W; tc.height = H;
  const tctx = tc.getContext('2d');
  tctx.fillStyle = 'white'; tctx.font = `900 ${size}px sans-serif`;
  tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
  tctx.fillText(txt, W/2, H/2 - 50); // લખાણ થોડું ઉપર રાખ્યું છે

  const data = tctx.getImageData(0, 0, W, H).data;
  let pts = [];
  for(let y=0; y<H; y+=6){
    for(let x=0; x<W; x+=6){
      if(data[(y * W + x) * 4 + 3] > 128) pts.push({x: x, y: y});
    }
  }
  return pts.length ? pts : [{x: W/2, y: H/2}];
}

function initZynk() {
  W = cvs.width = window.innerWidth;
  H = cvs.height = window.innerHeight;

  let s1 = getPts('ZYNK', Math.min(W/3, 100)); // Stage 1
  let s2 = []; // Stage 2: Orbit
  for(let i=0; i<pCount; i++) s2.push({x: Math.random() * W, y: Math.random() * H});

  let s3 = []; // Stage 3: Ocean Wave
  for(let i=0; i<pCount; i++){
    let nx = (i / pCount) * W;
    let ny = H/2 + Math.sin(nx * 0.04) * 50 + Math.cos(nx * 0.02) * 30;
    s3.push({x: nx, y: ny});
  }

  // Stage 4 માં પાર્ટીકલ્સ સ્ક્રીનની બહાર જતા રહેશે, કારણકે ગ્લોઇંગ કાર્ડ આવશે
  let s4 = [];
  for(let i=0; i<pCount; i++) s4.push({x: W/2 + (Math.random()-0.5)*3000, y: H/2 + (Math.random()-0.5)*3000});

  shapes = [s1, s2, s3, s4];

  particles = [];
  for(let i=0; i<pCount; i++){
    particles.push({x: W/2, y: H/2, c: `hsl(${180 + Math.random() * 80}, 100%, 60%)`}); // સાયન અને પર્પલ રંગો
  }
}
initZynk(); window.addEventListener('resize', initZynk);

let prog = 0;
mainWrap.addEventListener('scroll', () => {
  prog = mainWrap.scrollTop / (mainWrap.scrollHeight - mainWrap.clientHeight);

  document.getElementById('msg1').style.opacity = (prog < 0.1) ? 1 : 0;

  const m2 = document.getElementById('msg2');
  m2.style.opacity = (prog > 0.25 && prog < 0.45) ? 1 : 0;
  m2.style.transform = `scale(${1 + (prog - 0.25)})`;

  document.getElementById('msg3').style.opacity = (prog > 0.55 && prog < 0.75) ? 1 : 0;

  // અંતિમ કાર્ડ દેખાડવું
  if(prog > 0.85) document.getElementById('finalCard').classList.add('visible');
  else document.getElementById('finalCard').classList.remove('visible');
});

// મેગ્નેટિક બટન ઇફેક્ટ
const mBtn = document.getElementById('mBtn');
mBtn.addEventListener('pointermove', (e) => {
  const rect = mBtn.getBoundingClientRect();
  const x = (e.clientX - rect.left - rect.width/2) * 0.4;
  const y = (e.clientY - rect.top - rect.height/2) * 0.4;
  mBtn.style.transform = `translate(${x}px, ${y}px)`;
});
mBtn.addEventListener('pointerleave', () => mBtn.style.transform = `translate(0px, 0px)`);

function lerp(a, b, t){ return a + (b - a) * t; }

function drawZynk() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.3)'; // સ્મૂધ ટ્રેલ ઇફેક્ટ માટે
  ctx.fillRect(0, 0, W, H);

  let stage = prog * 3;
  let cS = Math.floor(stage);
  let nS = Math.min(cS + 1, 3);
  let t = stage - cS;

  let pts1 = shapes[cS], pts2 = shapes[nS];

  for(let i=0; i<pCount; i++){
    let p = particles[i];
    let t1 = pts1[i % pts1.length], t2 = pts2[i % pts2.length];

    let tx = lerp(t1.x, t2.x, t);
    let ty = lerp(t1.y, t2.y, t);

    if(cS === 1) { 
      tx += Math.sin(Date.now() * 0.001 + i) * 40;
      ty += Math.cos(Date.now() * 0.002 + i) * 40;
    }

    p.x += (tx - p.x) * 0.08; p.y += (ty - p.y) * 0.08;

    ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
    ctx.fillStyle = p.c; ctx.fill();
  }
  requestAnimationFrame(drawZynk);
}
drawZynk();
